import { readFileSync, readdirSync } from 'node:fs'
import { join } from 'node:path'
import { describe, expect, it } from 'vitest'
import type { SignRecording } from '../vision/types'
import { HAND_FINGERS, fingerDeviation } from './fingerStates'
import { HINT_MIN_DEVIATION, scoreAttempt } from './score'

// Read-only, opt-in calibration; no corpus is copied or generated by this test.
const dir = process.env.CALIBRATION_DIR ?? join(process.cwd(), 'calibration')
const byGloss = new Map<string, SignRecording[]>()
let names: string[] = []
try { names = readdirSync(dir).filter((n) => n.endsWith('.json')).sort() } catch { /* absent in CI */ }
for (const name of names) {
  const rec = JSON.parse(readFileSync(join(dir, name), 'utf8')) as SignRecording
  byGloss.set(rec.gloss, [...(byGloss.get(rec.gloss) ?? []), rec])
}
const glosses = [...byGloss.keys()].sort()
const q = (v: number[], p: number) => [...v].sort((a, b) => a - b)[Math.min(v.length - 1, Math.floor(p * v.length))]

describe.skipIf(glosses.length < 2)('L-17 read-only corpus evidence', () => {
  it.skipIf(!process.env.L17_BASELINE_MODULE)('keeps scores/distances/joints identical to the pre-L-17 scorer', async () => {
    const before = await import(/* @vite-ignore */ process.env.L17_BASELINE_MODULE!) as { scoreAttempt: typeof scoreAttempt }
    let pairs = 0
    for (let index = 0; index < glosses.length; index++) {
      const reference = byGloss.get(glosses[index])![0]
      const attempts = [...byGloss.get(glosses[index])!.slice(0, 6),
        ...byGloss.get(glosses[(index + 1) % glosses.length])!.slice(0, 4)]
      for (const attempt of attempts) {
        const project = (r: ReturnType<typeof scoreAttempt>) => ({ score: r.score,
          normalizedDistance: r.normalizedDistance, mirrored: r.mirrored, twoHanded: r.twoHanded,
          hands: r.hands.map(({ contributions: _costs, ...hand }) => hand), worstJoints: r.worstJoints })
        expect(project(scoreAttempt(attempt, reference))).toEqual(project(before.scoreAttempt(attempt, reference)))
        pairs++
      }
    }
    console.info(`Pre-L-17 scorer comparison: ${pairs} recorded pairs identical`)
  })
  it('measures finger cutoffs and finds a real trajectory-dominant pair', () => {
    const same: number[] = []
    const different: number[] = []
    let pathPair: { attempt: string; reference: string; shape: number; traj: number } | undefined
    const collect = (a: SignRecording, b: SignRecording, out: number[]) => {
      const result = scoreAttempt(a, b)
      for (const hand of result.hands) {
        if (hand.missing) continue
        for (const finger of HAND_FINGERS) out.push(fingerDeviation(hand.perLandmark, finger))
        if (!pathPair && hand.contributions && hand.contributions.traj > hand.contributions.shape
            && result.typedHints?.some((hint) => hint.kind === 'path')) {
          pathPair = { attempt: a.id, reference: b.id, ...hand.contributions }
        }
      }
    }
    glosses.forEach((gloss, index) => {
      const takes = byGloss.get(gloss)!.slice(0, 6)
      for (let i = 0; i < takes.length; i++)
        for (let j = 0; j < takes.length; j++)
          if (i !== j) collect(takes[i], takes[j], same)
      const other = byGloss.get(glosses[(index + 1) % glosses.length])!
      for (let i = 0; i < Math.min(takes.length, 4); i++) collect(other[i % other.length], takes[i], different)
    })
    // Finger-distribution sampling above is fixed to match the earlier audit.
    // Search separate real pairs for a path hint, without changing that sample.
    for (const a of glosses) {
      if (pathPair) break
      for (const b of glosses) {
        if (pathPair) break
        if (a === b) continue
        for (const attempt of byGloss.get(a)!.slice(0, 6)) {
          if (pathPair) break
          const reference = byGloss.get(b)![0]
          const result = scoreAttempt(attempt, reference)
          if (result.typedHints?.some((hint) => hint.kind === 'path')) {
            const contributions = result.hands.find((hand) => hand.contributions && hand.contributions.traj > hand.contributions.shape)!.contributions!
            pathPair = { attempt: attempt.id, reference: reference.id, ...contributions }
          }
        }
      }
    }
    const cutoff = q(same, 0.95)
    const share = (v: number[], cut: number) => v.filter((d) => d > cut).length / v.length
    console.info(JSON.stringify({
      takes: names.length, signs: glosses.length, sameFingers: same.length, differentFingers: different.length,
      sameP95: cutoff, sameAbovePoint1: share(same, 0.1), differentAboveP95: share(different, cutoff),
      sameP90: q(same, 0.9), differentMedian: q(different, 0.5), pathPair,
    }))
    expect(Number.isFinite(cutoff)).toBe(true)
    expect(Math.ceil(cutoff * 100) / 100).toBe(HINT_MIN_DEVIATION)
    // Existing evidence of overlap must still hold; no qualitative states
    // are validated by this candidate threshold or by a single-signer corpus.
    expect(q(different, 0.5)).toBeLessThan(q(same, 0.9))
    expect(pathPair).toBeDefined()
  }, 120_000)
})
